<template><div><div class="page-head"><div><h1>Sales</h1><p>Record sales and keep a clean transaction history.</p></div><button class="btn btn-primary" @click="openCreate">+ New sale</button></div><div class="card mb-4 p-4"><input v-model="search" @keyup.enter="load" class="input md:max-w-sm" placeholder="Search sale number…"></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>Sale</th><th>Client</th><th>Date</th><th>Total</th><th>Payment</th><th>Invoice</th><th>Status</th><th class="text-right">Action</th></tr></thead><tbody><tr v-for="s in sales" :key="s.id"><td><RouterLink :to="`/sales/${s.id}`" class="font-bold text-indigo-600">{{s.sale_number}}</RouterLink></td><td>{{s.client?.name||'Walk-in'}}</td><td>{{formatDate(s.sale_date)}}</td><td>{{money(s.total)}}</td><td class="capitalize">{{s.payment_status}}</td><td><RouterLink v-if="s.invoice_id || s.invoice?.id" :to="`/invoices/${s.invoice_id || s.invoice.id}`" class="font-bold text-indigo-600">{{s.invoice?.invoice_number || "Invoice"}}</RouterLink><span v-else>—</span></td><td><StatusBadge :value="s.status"/></td><td class="text-right"><button v-if="s.status!=='cancelled'" class="btn btn-danger" @click="voidSale(s)">Void</button></td></tr><tr v-if="!sales.length"><td colspan="8"><div class="empty">No sales yet.</div></td></tr></tbody></table></div><AppModal :open="open" title="New sale" subtitle="Add items, choose the customer and complete the transaction." @close="open=false"><form @submit.prevent="save"><div class="grid gap-4 md:grid-cols-3"><div><label class="label">Customer</label><select v-model="form.client_id" class="input"><option :value="null">Walk-in customer</option><option v-for="c in clients" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div><label class="label">Payment status</label><select v-model="form.payment_status" class="input"><option value="paid">Paid</option><option value="credit">Credit</option></select><p v-if="form.payment_status==='credit'" class="mt-1 text-[11px] text-amber-600">A client is required. A 30-day invoice will be created automatically.</p></div><div v-if="form.payment_status==='paid'"><label class="label">Payment method</label><select v-model="form.payment_method" class="input"><option value="cash">Cash</option><option value="bank">Bank</option><option value="mpesa">M-Pesa</option><option value="airtel_money">Airtel Money</option><option value="tigopesa">Mixx by Yas</option><option value="halopesa">HaloPesa</option><option value="card">Card</option><option value="cheque">Cheque</option><option value="other">Other</option></select></div></div><div class="mt-5 rounded-2xl border border-slate-100 bg-slate-50/60 p-4"><div class="mb-3 flex items-center justify-between"><div class="text-xs font-bold">Line items</div><button type="button" class="btn btn-soft" @click="addItem">+ Add item</button></div><div v-for="(item,i) in form.items" :key="i" class="mb-2 grid grid-cols-[1fr_90px_120px_32px] gap-2"><select v-model="item.product_id" class="input" @change="priceFromProduct(item)" required><option :value="null">Select item</option><option v-for="p in products" :key="p.id" :value="p.id">{{p.name}} — {{money(p.selling_price)}}</option></select><input v-model.number="item.quantity" class="input" type="number" min="0.001" step="0.001"><MoneyInput v-model="item.unit_price" :min="0" /><button type="button" class="icon-btn" @click="form.items.splice(i,1)" :disabled="form.items.length===1">×</button></div></div><div class="mt-5 flex items-end justify-between"><div><label class="label">Discount</label><MoneyInput v-model="form.discount" class="max-w-40" :min="0" /></div><div class="text-right"><div class="text-[10px] uppercase tracking-wider text-slate-400">Estimated total</div><div class="text-2xl font-extrabold">{{money(total)}}</div></div></div><div class="mt-5 flex justify-end gap-2 border-t border-slate-100 pt-4"><button type="button" class="btn btn-soft" @click="open=false">Cancel</button><button class="btn btn-primary">{{saving?'Saving…':'Complete sale'}}</button></div></form></AppModal><div v-if="error" class="fixed bottom-5 right-5 rounded-xl bg-rose-600 px-4 py-3 text-xs font-bold text-white shadow-xl">{{error}}</div></div></template>
<script setup lang="ts">import MoneyInput from '../../components/MoneyInput.vue';import {computed,onMounted,ref} from 'vue';import {api,apiError} from '../../services/api';import {formatDateTime} from '../../utils/date';import {useConfirm} from '../../stores/confirm';import {useToast} from '../../stores/toast';import AppModal from '../../components/AppModal.vue';import StatusBadge from '../../components/StatusBadge.vue';const {ask:confirm}=useConfirm();const toast=useToast();const sales=ref<any[]>([]),clients=ref<any[]>([]),products=ref<any[]>([]),search=ref(''),open=ref(false),saving=ref(false),error=ref('');const blankItem=()=>({product_id:null,quantity:1,unit_price:0,discount:0});const form=ref<any>({client_id:null,payment_status:'paid',payment_method:'cash',payment_reference:'',discount:0,notes:'',items:[blankItem()]});const total=computed(()=>Math.max(0,form.value.items.reduce((s:any,i:any)=>{const line=Math.max(0,Number(i.quantity||0)*Number(i.unit_price||0)-Number(i.discount||0));const p=products.value.find((x:any)=>x.id===i.product_id);return s+line+(line*Number(p?.tax_rate||0)/100)},0)-Number(form.value.discount||0)));
function priceFromProduct(i:any){const p=products.value.find((x:any)=>x.id===i.product_id);if(p)i.unit_price=Number(p.selling_price)}function money(v:any){return new Intl.NumberFormat('en-TZ',{style:'currency',currency:'TZS',maximumFractionDigits:0}).format(Number(v||0))}function formatDate(v:any){return formatDateTime(v)}async function load(){sales.value=(await api.get('/sales',{params:{search:search.value,per_page:30}})).data.data}async function openCreate(){const [c,p]=await Promise.all([api.get('/clients',{params:{per_page:100}}),api.get('/products',{params:{per_page:100,active:true}})]);clients.value=c.data.data;products.value=p.data.data;form.value={client_id:null,payment_status:'paid',payment_method:'cash',payment_reference:'',discount:0,notes:'',items:[blankItem()]};error.value='';open.value=true}function addItem(){form.value.items.push(blankItem())}async function save(){if(form.value.payment_status==='credit'&&!form.value.client_id){error.value='A credit sale requires a client because an invoice will be created.';toast.warning('Client required', error.value);return} saving.value=true;error.value='';try{await api.post('/sales',form.value);open.value=false;await load();toast.success('Sale completed','The sale was recorded successfully.')}catch(e){error.value=apiError(e);toast.error('Action failed', apiError(e))}finally{saving.value=false}}async function voidSale(s:any){if(!(await confirm({title:'Void sale?',message:`${s.sale_number} will be voided and stock will be restored. This action cannot be undone.`,confirmText:'Void sale',danger:true})))return;try{await api.delete(`/sales/${s.id}`);await load();toast.success('Sale voided', `${s.sale_number} was voided and stock restored.`)}catch(e){error.value=apiError(e);toast.error('Action failed', apiError(e))}}onMounted(load)</script>
